<!doctype html>
<html lang="en">
<head>
  <meta charset="utf-8">
  <meta name="viewport" content="width=device-width, initial-scale=1">
  <title>Kanban Board</title>
  <style>
    :root {
      --bg: #f4f7fb;
      --panel: #ffffff;
      --text: #1d2939;
      --muted: #667085;
      --border: #dce3ed;
      --accent: #4f46e5;
      --accent-soft: #eef2ff;
      --danger: #e11d48;
      --shadow: 0 8px 22px rgba(31, 41, 55, 0.08);
    }

    * {
      box-sizing: border-box;
    }

    body {
      margin: 0;
      min-height: 100vh;
      background: var(--bg);
      color: var(--text);
      font-family: Arial, Helvetica, sans-serif;
    }

    .app {
      max-width: 1280px;
      margin: 0 auto;
      padding: 34px 22px 48px;
    }

    h1 {
      margin: 0 0 24px;
      font-size: clamp(1.7rem, 4vw, 2.35rem);
      letter-spacing: -0.04em;
    }

    .add-form {
      display: flex;
      gap: 10px;
      margin-bottom: 26px;
    }

    #new-card {
      flex: 1;
      min-width: 0;
      padding: 13px 15px;
      border: 1px solid var(--border);
      border-radius: 10px;
      outline: none;
      background: #fff;
      color: var(--text);
      font-size: 1rem;
      transition: border-color 0.2s, box-shadow 0.2s;
    }

    #new-card:focus {
      border-color: var(--accent);
      box-shadow: 0 0 0 3px rgba(79, 70, 229, 0.14);
    }

    #add-card {
      border: 0;
      border-radius: 10px;
      padding: 0 19px;
      background: var(--accent);
      color: white;
      font-weight: 700;
      font-size: 0.95rem;
      cursor: pointer;
      transition: background 0.2s, transform 0.2s;
    }

    #add-card:hover {
      background: #4338ca;
    }

    #add-card:active {
      transform: translateY(1px);
    }

    .board {
      display: grid;
      grid-template-columns: repeat(3, minmax(0, 1fr));
      gap: 18px;
      align-items: start;
    }

    .column {
      min-height: 420px;
      border: 1px solid var(--border);
      border-radius: 15px;
      background: rgba(255, 255, 255, 0.72);
      overflow: hidden;
      transition: background 0.2s, border-color 0.2s;
    }

    .column.drag-over {
      border-color: var(--accent);
      background: var(--accent-soft);
    }

    .column-header {
      display: flex;
      justify-content: space-between;
      align-items: center;
      padding: 16px 16px 14px;
      border-bottom: 1px solid var(--border);
      background: rgba(255, 255, 255, 0.85);
    }

    .column-header h2 {
      margin: 0;
      font-size: 1rem;
      letter-spacing: -0.01em;
    }

    .count {
      display: inline-flex;
      justify-content: center;
      align-items: center;
      min-width: 26px;
      height: 26px;
      padding: 0 8px;
      border-radius: 999px;
      background: #e9edf5;
      color: #475467;
      font-size: 0.82rem;
      font-weight: 700;
    }

    .card-container {
      min-height: 350px;
      padding: 12px;
    }

    .card {
      display: flex;
      align-items: flex-start;
      gap: 10px;
      margin-bottom: 10px;
      padding: 13px;
      border: 1px solid #e4e8f0;
      border-radius: 11px;
      background: var(--panel);
      box-shadow: 0 3px 9px rgba(31, 41, 55, 0.06);
      cursor: grab;
      user-select: none;
      transition: box-shadow 0.18s, transform 0.18s, opacity 0.18s;
    }

    .card:hover {
      transform: translateY(-1px);
      box-shadow: var(--shadow);
    }

    .card.dragging {
      opacity: 0.45;
      cursor: grabbing;
    }

    .card-title {
      flex: 1;
      min-width: 0;
      line-height: 1.4;
      overflow-wrap: anywhere;
    }

    .card-del {
      flex: 0 0 auto;
      width: 27px;
      height: 27px;
      margin: -3px -3px 0 0;
      border: 0;
      border-radius: 7px;
      background: transparent;
      color: var(--muted);
      font-size: 1.25rem;
      line-height: 1;
      cursor: pointer;
    }

    .card-del:hover {
      background: #fff1f2;
      color: var(--danger);
    }

    @media (max-width: 760px) {
      .board {
        grid-template-columns: 1fr;
      }

      .column {
        min-height: 220px;
      }

      .card-container {
        min-height: 150px;
      }
    }
  </style>
</head>
<body>
  <main class="app">
    <h1>My Kanban Board</h1>

    <div class="add-form">
      <input id="new-card" type="text" placeholder="Add a task…" aria-label="New task">
      <button id="add-card" type="button">Add Card</button>
    </div>

    <section class="board" aria-label="Kanban board">
      <section class="column" id="col-todo" aria-labelledby="todo-heading">
        <header class="column-header">
          <h2 id="todo-heading">To Do</h2>
          <span class="count">0</span>
        </header>
        <div class="card-container" aria-label="To Do cards"></div>
      </section>

      <section class="column" id="col-doing" aria-labelledby="doing-heading">
        <header class="column-header">
          <h2 id="doing-heading">Doing</h2>
          <span class="count">0</span>
        </header>
        <div class="card-container" aria-label="Doing cards"></div>
      </section>

      <section class="column" id="col-done" aria-labelledby="done-heading">
        <header class="column-header">
          <h2 id="done-heading">Done</h2>
          <span class="count">0</span>
        </header>
        <div class="card-container" aria-label="Done cards"></div>
      </section>
    </section>
  </main>

  <script>
    (function () {
      "use strict";

      const STORAGE_KEY = "kanban-board-state-v1";
      const columnIds = ["col-todo", "col-doing", "col-done"];
      const input = document.getElementById("new-card");
      const addButton = document.getElementById("add-card");
      let draggedCard = null;

      function makeCardId() {
        if (window.crypto && crypto.randomUUID) {
          return crypto.randomUUID();
        }
        return "card-" + Date.now() + "-" + Math.random().toString(16).slice(2);
      }

      function getContainer(columnId) {
        return document.querySelector("#" + columnId + " .card-container");
      }

      function updateCounts() {
        columnIds.forEach(function (columnId) {
          const column = document.getElementById(columnId);
          column.querySelector(".count").textContent =
            column.querySelectorAll(".card").length;
        });
      }

      function saveBoard() {
        const state = {};

        columnIds.forEach(function (columnId) {
          state[columnId] = Array.from(
            getContainer(columnId).querySelectorAll(".card")
          ).map(function (card) {
            return {
              id: card.dataset.cardId,
              title: card.querySelector(".card-title").textContent
            };
          });
        });

        try {
          localStorage.setItem(STORAGE_KEY, JSON.stringify(state));
        } catch (error) {
          /* Storage may be unavailable; the board remains usable in memory. */
        }
      }

      function createCard(title, cardId) {
        const card = document.createElement("article");
        card.className = "card";
        card.draggable = true;
        card.dataset.cardId = cardId || makeCardId();

        const cardTitle = document.createElement("span");
        cardTitle.className = "card-title";
        cardTitle.textContent = title;

        const deleteButton = document.createElement("button");
        deleteButton.className = "card-del";
        deleteButton.type = "button";
        deleteButton.setAttribute("aria-label", "Delete card");
        deleteButton.textContent = "×";

        deleteButton.addEventListener("click", function () {
          card.remove();
          updateCounts();
          saveBoard();
        });

        card.addEventListener("dragstart", function (event) {
          draggedCard = card;
          card.classList.add("dragging");
          event.dataTransfer.effectAllowed = "move";
          event.dataTransfer.setData("text/plain", card.dataset.cardId);
        });

        card.addEventListener("dragend", function () {
          card.classList.remove("dragging");
          draggedCard = null;
          document.querySelectorAll(".column").forEach(function (column) {
            column.classList.remove("drag-over");
          });
        });

        card.append(cardTitle, deleteButton);
        return card;
      }

      function addNewCard() {
        const title = input.value.trim();
        if (!title) return;

        getContainer("col-todo").appendChild(createCard(title));
        input.value = "";
        input.focus();
        updateCounts();
        saveBoard();
      }

      function restoreBoard() {
        let state;

        try {
          state = JSON.parse(localStorage.getItem(STORAGE_KEY));
        } catch (error) {
          state = null;
        }

        if (!state || typeof state !== "object") {
          updateCounts();
          return;
        }

        columnIds.forEach(function (columnId) {
          if (!Array.isArray(state[columnId])) return;

          state[columnId].forEach(function (savedCard) {
            if (
              savedCard &&
              typeof savedCard.title === "string" &&
              savedCard.title.trim()
            ) {
              getContainer(columnId).appendChild(
                createCard(savedCard.title, savedCard.id)
              );
            }
          });
        });

        updateCounts();
      }

      document.querySelectorAll(".column").forEach(function (column) {
        column.addEventListener("dragover", function (event) {
          event.preventDefault();
          event.dataTransfer.dropEffect = "move";
          column.classList.add("drag-over");
        });

        column.addEventListener("dragleave", function (event) {
          if (!column.contains(event.relatedTarget)) {
            column.classList.remove("drag-over");
          }
        });

        column.addEventListener("drop", function (event) {
          event.preventDefault();
          column.classList.remove("drag-over");

          const draggedId = event.dataTransfer.getData("text/plain");
          const card = draggedCard || Array.from(document.querySelectorAll(".card"))
            .find(function (item) {
              return item.dataset.cardId === draggedId;
            });

          if (card) {
            column.querySelector(".card-container").appendChild(card);
            updateCounts();
            saveBoard();
          }
        });
      });

      addButton.addEventListener("click", addNewCard);

      input.addEventListener("keydown", function (event) {
        if (event.key === "Enter") {
          addNewCard();
        }
      });

      restoreBoard();
    })();
  </script>
</body>
</html>
